mapper.update:
update sys_project_defect_field
field_label = #{fieldLabel}, field_type = #{fieldType}, max_length = #{maxLength}, required = #{required}, nullable = #{nullable}, enabled = #{enabled}, sort_order = #{sortOrder}, type_config = #{typeConfig, typeHandler=com.cat2bug.system.mybatis.JsonMapTypeHandler}, default_value = #{defaultValue, typeHandler=com.cat2bug.system.mybatis.JsonValueTypeHandler}, update_time = #{updateTime},
where field_id = #{fieldId} and team_id = #{teamId}

update sys_team
set defect_builtin_field_config = #{config},
    update_time = #{updateTime,jdbcType=TIMESTAMP}
where team_id = #{teamId}
